-- pipeline/recent-runs
-- The latest runs for the review area: when, how started, the outcome and the counts.
--
-- Parameters, with the example values used to render this file:
--   $1 = 10
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

select "id", "trigger", "status", "created_at", "finished_at", "items_new", "candidates_new", "error"
from "pipeline_runs"
order by "pipeline_runs"."created_at" desc
limit $1;
